state.dashboardGalera='';
function phase4CanSeeGaleraKpis(){return ['ADMIN_TOTAL','ADMIN','SISTEMA','PAGADOR','GERENTE_GALERA'].includes(role())}
function phase4OpenGalera(galera){const box=document.querySelector('#phase4GaleraDetail');if(!box)return;box.innerHTML=`<div class="galera-detail"><div class="galera-detail-head"><div><b>${esc(galera)}</b><div class="muted">Selecciona el detalle que deseas revisar.</div></div><div class="galera-detail-actions"><button data-gal-neg="${esc(galera)}">Ver negativos</button><button class="soft-btn" data-gal-pay="${esc(galera)}">Ver pagos</button></div></div></div>`;box.querySelector('[data-gal-neg]').onclick=()=>{state.dashboardGalera=galera;goModule('negativos_hoy')};box.querySelector('[data-gal-pay]').onclick=()=>{state.dashboardGalera=galera;goModule('pagos_hoy')};box.scrollIntoView({behavior:'smooth',block:'nearest'})}
async function phase4RenderGaleraKpis(v){const old=v.querySelector('#rotationFeed');if(old)old.remove();if(!phase4CanSeeGaleraKpis())return;try{const rows=await rpc('panapass_dashboard_galeras');const anchor=v.querySelector('.dashboard-welcome')||v.querySelector('.kpis');if(!anchor)return;const wrap=document.createElement('section');wrap.className='galera-kpi-section';wrap.id='phase4GaleraKpis';wrap.innerHTML=`<div class="galera-kpi-title"><div><h3>Resumen por galera</h3><span>Vista general de las 4 galeras. Haz clic para abrir detalle.</span></div></div><div class="galera-kpi-grid">${(rows||[]).map(r=>`<article class="galera-kpi" data-galera-kpi="${esc(r.galera)}"><span class="gname">${esc(r.galera)}</span><div class="gmetrics"><div class="gm"><span>Unidades</span><b>${Number(r.unidades||0)}</b></div><div class="gm bad"><span>Negativos</span><b>${Number(r.negativos||0)}</b></div><div class="gm good"><span>Pagadas hoy</span><b>${Number(r.unidades_pagadas||0)}</b></div></div><div class="gmetrics" style="margin-top:7px;grid-template-columns:1fr 1fr"><div class="gm bad"><span>Saldo negativo</span><b>${money(r.saldo_negativo||0)}</b></div><div class="gm good"><span>Monto pagado</span><b>${money(r.monto_pagado||0)}</b></div></div></article>`).join('')}</div><div id="phase4GaleraDetail"></div>`;anchor.insertAdjacentElement('afterend',wrap);wrap.querySelectorAll('[data-galera-kpi]').forEach(card=>card.onclick=()=>phase4OpenGalera(card.dataset.galeraKpi))}catch(e){console.warn('KPIs galeras:',e)}}
const _phase4Dashboard=dashboard;dashboard=async function(v){await _phase4Dashboard(v);const rot=v.querySelector('#rotationFeed');if(rot)rot.remove();await phase4RenderGaleraKpis(v)};
const _phase4Negativos=negativos;negativos=async function(v){const gal=state.dashboardGalera||'';await _phase4Negativos(v);if(gal){const sel=document.querySelector('#p3NegGalera');if(sel&&[...sel.options].some(o=>o.value===gal)){sel.value=gal;state.dashboardGalera='';sel.dispatchEvent(new Event('change'))}}};
const _phase4PagosConsulta=pagosConsultaHoy;pagosConsultaHoy=async function(v){const gal=state.dashboardGalera||'';await _phase4PagosConsulta(v);if(gal){const sel=document.querySelector('#p3PayGalera');if(sel&&[...sel.options].some(o=>o.value===gal)){sel.value=gal;state.dashboardGalera='';sel.dispatchEvent(new Event('change'))}}};
